const listWorkspaceBudgetStates = `-- name: ListWorkspaceBudgetStates :many

SELECT b.id, b.workspace_id, b.scope_type, b.scope_id, b.period, b.amount_micros,
       b.soft_percent, b.mode, b.classes, b.status, b.created_by, b.created_at, b.updated_at,
       COALESCE(p.spent_micros, 0)::bigint AS spent_micros,
       COALESCE(p.extended_micros, 0)::bigint AS extended_micros,
       COALESCE(p.runs, 0)::integer AS runs,
       p.period_start, p.period_end
FROM budget b
LEFT JOIN budget_period p
  ON p.budget_id = b.id AND p.period_start <= $1::timestamptz AND p.period_end > $1::timestamptz
WHERE b.workspace_id = $2::uuid
ORDER BY b.scope_type, b.created_at, b.id
`

type ListWorkspaceBudgetStatesParams struct {
	Now         pgtype.Timestamptz `json:"now"`
	WorkspaceID pgtype.UUID        `json:"workspace_id"`
}

type ListWorkspaceBudgetStatesRow struct {
	ID             pgtype.UUID        `json:"id"`
	WorkspaceID    pgtype.UUID        `json:"workspace_id"`
	ScopeType      string             `json:"scope_type"`
	ScopeID        pgtype.UUID        `json:"scope_id"`
	Period         string             `json:"period"`
	AmountMicros   int64              `json:"amount_micros"`
	SoftPercent    int32              `json:"soft_percent"`
	Mode           string             `json:"mode"`
	Classes        []string           `json:"classes"`
	Status         string             `json:"status"`
	CreatedBy      pgtype.UUID        `json:"created_by"`
	CreatedAt      pgtype.Timestamptz `json:"created_at"`
	UpdatedAt      pgtype.Timestamptz `json:"updated_at"`
	SpentMicros    int64              `json:"spent_micros"`
	ExtendedMicros int64              `json:"extended_micros"`
	Runs           int32              `json:"runs"`
	PeriodStart    pgtype.Timestamptz `json:"period_start"`
	PeriodEnd      pgtype.Timestamptz `json:"period_end"`
}

// Budgets (spec 4.2). Attribution: a task belongs to a squad through
// agent_task_queue.squad_id, else its agent's home squad; to a floor through
// its squad; to an initiative through its backing issue or any issue of the
// initiative's build project. Spend is accounted per task into budget_period.
// Every budget of the workspace with its current period's counters. The period
// join matches the row whose window contains @now; a budget with no spend yet
// has no row, and its counters read as zero.
func (q *Queries) ListWorkspaceBudgetStates(ctx context.Context, arg ListWorkspaceBudgetStatesParams) ([]ListWorkspaceBudgetStatesRow, error) {
	rows, err := q.db.Query(ctx, listWorkspaceBudgetStates, arg.Now, arg.WorkspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListWorkspaceBudgetStatesRow{}
	for rows.Next() {
		var i ListWorkspaceBudgetStatesRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ScopeType,
			&i.ScopeID,
			&i.Period,
			&i.AmountMicros,
			&i.SoftPercent,
			&i.Mode,
			&i.Classes,
			&i.Status,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.SpentMicros,
			&i.ExtendedMicros,
			&i.Runs,
			&i.PeriodStart,
			&i.PeriodEnd,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockBudgetTaskForAccounting = `-- name: LockBudgetTaskForAccounting :one
SELECT t.id, a.workspace_id, t.created_at, t.budget_accounted_micros,
       COALESCE(t.squad_id, a.home_squad_id) AS squad_id,
       (SELECT s.floor_id FROM squad s WHERE s.id = COALESCE(t.squad_id, a.home_squad_id)) AS floor_id,
       (SELECT ini.id FROM initiative ini
         LEFT JOIN issue iss ON iss.id = t.issue_id
         WHERE ini.workspace_id = a.workspace_id
           AND (ini.issue_id = t.issue_id OR (iss.project_id IS NOT NULL AND ini.build_project_id = iss.project_id))
         ORDER BY ini.created_at, ini.id
         LIMIT 1) AS initiative_id
FROM agent_task_queue t
JOIN agent a ON a.id = t.agent_id
WHERE t.id = $1::uuid
FOR UPDATE OF t
`

type LockBudgetTaskForAccountingRow struct {
	ID                    pgtype.UUID        `json:"id"`
	WorkspaceID           pgtype.UUID        `json:"workspace_id"`
	CreatedAt             pgtype.Timestamptz `json:"created_at"`
	BudgetAccountedMicros int64              `json:"budget_accounted_micros"`
	SquadID               pgtype.UUID        `json:"squad_id"`
	FloorID               pgtype.UUID        `json:"floor_id"`
	InitiativeID          pgtype.UUID        `json:"initiative_id"`
}

// The task row and its attribution, locked so two accounting passes over the
// same task serialise.
func (q *Queries) LockBudgetTaskForAccounting(ctx context.Context, taskID pgtype.UUID) (LockBudgetTaskForAccountingRow, error) {
	row := q.db.QueryRow(ctx, lockBudgetTaskForAccounting, taskID)
	var i LockBudgetTaskForAccountingRow
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.CreatedAt,
		&i.BudgetAccountedMicros,
		&i.SquadID,
		&i.FloorID,
		&i.InitiativeID,
	)
	return i, err
}

const lockBudgetWorkspace = `-- name: LockBudgetWorkspace :exec
SELECT pg_advisory_xact_lock(hashtextextended('budget:' || $1::text, 0))
`

// Serialises budget accounting and budget creation per workspace, so a new
// budget's backfill and a concurrent accounting pass cannot both count a task.
func (q *Queries) LockBudgetWorkspace(ctx context.Context, workspaceID string) error {
	_, err := q.db.Exec(ctx, lockBudgetWorkspace, workspaceID)
	return err
}

